) AS (
  VALUES 
    (54::BIGINT, 'A la hora de explicar los temas y de desarrollarlos, parte como si uno ya supiera. A día de hoy, nunca había tenido un profesor que explicara tan mal. Preparese para tener que entender la materia por su cuenta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '4ca387a6ff047dbd2cbc922259641a0b873ad7794afb3fa98eaac1fbebebc860'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'La verdad desde mi punto de vista con este profesor aplicaría el término de "las apariencias engañan" puede que la primera impresión parezca un profesor cómico pero diría que es alguien muy controlador si algo no sale como él quiere suelta comentarios algo pesados hasta diría que humillante.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-08-16T00:00:00+00:00'::TIMESTAMPTZ, '8e3288ab2a6bf6c8f4e0ca27243ca3c6b360ea3bbfb8c2e7279e21425cbd42eb'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'El profesor posee una metodología efectiva: las clases presenciales facilitan la comprensión y tiene mucha disposición para atender dudas, hay tareas grupales casi todas las semanas, lo que hace indispensable contar con un equipo de trabajo sólido. Uno de los mejores profes que he tenido en el TEC.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'cb1abe3cc4845bbc5d22a09dbf35117f14f27aed3f52602199a02bc1a559878c'::TEXT, ARRAY[2374, 1892]::BIGINT[]),
    (54::BIGINT, 'La clase con el profesor es muy llevadera, logra dar ejemplos que los estudiantes entienden y por parte de las clases es muy claro. Se nota mucho su amor por la materia y por explicar. Da mucha retroalimentación y difícilmente va a calificar algo de manera que le perjudique al estudiante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Pocos exámenes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '137bdd6c6c60680e592e7785a3458816b824b0d865ac99347fe21c9821409448'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Dejó tareas que ni calificaba ni tenían nota, uno debía hacerlas para tenerlo de buen humor. Él no daba la clase, solo nos mandaba a ver videos y luego ver si vimos los videos. Los desafíos horribles (tenga una empresa manufacturera a mano), a nosotros nos llegó a eximir por promedio de desafíos.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2025-07-20T00:00:00+00:00'::TIMESTAMPTZ, '99a507af519d0e5e968e939be36124a0531b3db39332bd953d709a9334302838'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'Como profesional se ve que sabe mucho, pero como profesor es malo, prácticamente uno aprende solo. Él es medio pesado con sus comentarios, pero no es mala persona. No se aprende mucho, no lo recomiendo y por mi parte no quiero que sea mi profe de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '7391e427ea85bad31b0d9b139baaddf473317b95d5524a1522639b04d460d150'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Es un profesor que le importan sus estudiantes. Además de saber transmitir la materia y de enseñar las razones por las que es útil en la vida profesional. Es el mejor profesor que he tenido y un gran ser humano'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '1bc5ce6a48a048c6aec7826d36fa5cfde215bae00d70180a07bdeba39816c90d'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Juega de intrépido, se hace el misterioso, sus pdfs no dan instrucciones claras, no responde las dudas, trabajos largos, etc…'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-03-18T00:00:00+00:00'::TIMESTAMPTZ, '65356b3d7c3e77f29602b4b99ff5579773c797a7cb37eca8115b639d5b5e0029'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'En todo lo que llevo de carrera universitaria ha sido el peor profesor que he tenido.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'beda40c2ed98e4b713988d68f6f147daa86ac721147679a1b4b7ced01354a430'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Excelente profe. Si el nota que ud le pone hasta lo exime. Las clases pueden ser un poco largas pero los trabajos/pruebas son súper fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9d00a89658a1a49f7d74eb44a90c425cae8dcd418fcd24931bf97bd76d788e15'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'Es súper lindo, lo amo, ayuda un montón, le importan sus estudiantes, dispuesto al diálogo, de verdad que si lo odian es porque fueron vagos o están tont1t0s, el curso es super fácil, se pasa sin estudiar. Realmente se aprende'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'b8151c899c6055f19254b35dcc741feb2d1be4abd7947ec06b477b9ef71664cf'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'muy buen profesor, ayuda mucho con la calificación siempre y cuando vea que la gente lo intenta, se molesta mucho si la gente no pone atención o si se pone a hablar en clase. El curso es bastante duro en términos de que no da tiempo para estudiar a profundidad toda la materia antes del examen'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '72bb562252f3903dab99ea4068b38ba8fcadd98eae0659b35066ceb579bde87a'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'Las tareas son grupales, actualmente empezó a ver R por aquello, así que trabaja parecido a Cindy. Si le toca llevar con él y no tiene otra opción pues tampoco es TAN malo, es ponerle bastante atención a las clases, comprensivo con los estudiantes y si pide ayuda él la da.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'La participación importa']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'dcef0afcb961d054a3a3e69b432a6763ed054300a37cf78de186df4b886c4feb'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'El mejor profesor que he tenido en el TEC, no entiendo realmente las quejas por parte de los estudiantes, lo recomiendo sobre Cindy y Martín, se preocupa por el estudiante, busca que este pase, y busca beneficiar al estudiante en general, lo respeto, y volvería a matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '80f4f9b103b66e14e8b96ad86e945a354b0856091f12252beff609320a87bc86'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'DEMASIADO MALOO, NO PIERDAN EL TIEMPO, ES UN SEÑOR PREPOTENTE, LE GUSTA HUMILLAR Y NO DA CLASES, SOLO LEER Y DAR UNOS PDF REFRITOS'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '26f7b79a2480b800ae9ec6ac9d40c16dc053678bb77c738d0790f45366eb37cd'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'Es el peor profesor que he tenido a lo largo de la carrera. Su única función en clases es leer diapositivas y ya con eso da la materia por vista. Sin mencionar que denota un clasismo increíble, parece que olvida que es docente en una universidad pública.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a3c1a1150d4145e0378af938ee78013f56492de2fca638e5a35d806b19df1330'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'El profesor realmente se esfuerza por preparar bien sus clases y le interesa ayudar a los alumnos. Si se lleva la materia al día se logra de manera excelente. Lo Mejor de todo es que no aprendes para un examen sino para tu vida profesional. Ampliamente recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'dbb457471acf9300da2f2517d6a454ada3d64d8b84c897272a2e6ab75088bdbe'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'Es el peor literalmente, por favor no consideren para nada matricular nada con el..es increíble...cuando matricule leí estos comentarios y dije "no no puede ser tan malo"....y efectivamente lo confirmé. Las clases son fatales, él piensa que solo existe ese curso y los trabajos son suuper extensos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2022-04-21T00:00:00+00:00'::TIMESTAMPTZ, '181bb17a1edc6908c1dda80459d83a8fac2ed73430b3a82cf6747a9c52f8382d'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'El peor profesor que he tenido en mis 5 años de carrera, ya estoy llevando licenciatura y nunca he conocido un peor profesor, la retroalimentación es NULA y nunca le va a poder apelar un punto porque siempre se pone en varas. En serio, no lo lleve, no piense "Tal vez no es tan feo" En serio, nunca'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-09-08T00:00:00+00:00'::TIMESTAMPTZ, '14c256f557ab337d42ae86e39878ffbb9f305497bd9e3f984048840512508f11'::TEXT, ARRAY[2464]::BIGINT[]),
    (54::BIGINT, 'Fatal como profesor, confunde la definición de aula invertida, lo menos pedagógico que se puede ser. La asistencia no es obligatoria pero el pasa lista igual.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'ad73c5dee2322f13b86e168dbe127df43f5d6345c39db0a466b3e6eb6d5f1488'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'El profesor, en todo el semestre no dio una clase magistral, se baso solo en las guías de aula invertida donde el estudiante era el que llegaba a presentar en cada clase.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c1b91eaea009b2d433751547d2bc2503e1b108e7ebb2c606fe6966691e3ce055'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'De verdad el peor profe con el que he matriculado. Deja el proyecto super tarde y es larguísimo y super confuso, todo el curso en general es super confuso y ni da clases y es super desordenado Jamás matriculen con el'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'c2bf22a18a838fc0c438439de039eee6ffbf8dcec7e44464a6bcf8e88e646865'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'MUY EXIGENTE PERO SI APRENDES'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-07-09T00:00:00+00:00'::TIMESTAMPTZ, '1ff592b62135937c309c39a9cdb3290669df6a8d3eac53b06edd6e9ebf89af1f'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Este curso lo dan solo 4 profesores y el es su mejor opción. El profe es amable y le gusta que participen. Lo malo es que no da clases presenciales, todo es con videos muy lentos y aburridos. Por eso no queda clara la materia. Los exámenes y trabajos no son del todo claros. Y clases aburridas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '73a35fa1b331bf5b26b8a127181d738a65e18e22b0ed8a1652fba4ecef82b2d0'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'Es un pesimo profesor, en todo el semestre NUNCA dio una clase magistral, se baso solo en las guias basadas del libro y aula invertida que practicamente el estudiante da la clase ¡NO! matriculen con el'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-05-18T00:00:00+00:00'::TIMESTAMPTZ, '07fe3e2a60631411707c10ac5c77a9de677b6fe17488a441eb6f70a3f513fd61'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Pésimo profesor. Tanto virtual como presencial. Hipócrita, no ayuda, baja puntos de la nada, si anda de malas sepa que lo va a calificar mal, no se entiende lo que quiere, nunca se le queda bien, es prepotente y ni se le ocurra corregirlo porque la agarra contra usted.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, '54cc54fdf6ef12f6255f5696404bcc3788a0774c78ca16ae214a816760ac5c67'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'Es un profesor poco profesional. Necesita todo al tiempo de él e hipócrita con los estudiantes. Baja puntos por cosas muy tontas. Piensa que los estudiantes están 100% a disposición de él. No le importa ni el aprendizaje ni el bienestar de sus estudiantes. Si quieren salud mental, no matriculen.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a0b3f3bf08d0648230f90af6433c3a0527b88874fb93192fb90f57dcb21cfee2'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'El profesor nunca ayuda o aclara dudas, en lugar de ayudar juzga a los estudiantes, se burla de ellos. Es muy hipocrita y le gusta hacer sufrir a los estudiantes, es poco empatico y no esta abierto a negociar notas. No me parece que haga muy bien su trabajo como educador en pro de los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '37375a474c3487ec6a71d11d0656123eb156b570024992e68b2a269594c9ba44'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'No es alguien que explique bien la materia y cuando uno le preguntoa lo que no entenció no se toma en serio las dudas. Hace examenes con pocos puntos y luego baja puntos a lo loco. Sus clases son largas y difíciles de entender. Pide autogestión y luego califica de mala manera lo que uno aprenidó.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'f3adb187c157c5ce6f933593f5656793c993f8736ddc31e913bba7f500ef49ca'::TEXT, ARRAY[1892, 2374]::BIGINT[]),
    (54::BIGINT, 'El profe es demasiado pedante, hipócrita, se burla del estudiante continuamente, los exámenes tienen un puntaje muy bajo y baja puntos sin medida, no se le puede reclamar nada porque nunca da el brazo a torcer, no explica nunca, los quices no son con la materia vista en clase, manipulador'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'f71ac6220e28773e040a37129bdcbcb7122e1b9e2e3c73a272a763681a2bb41e'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Este semestre que fue virtual, dio si acaso 2 clases sincrónicas. Para los exámenes no explicaba NADA. Hubo un examen en donde las instrucciones eran 0 claras y cuando le preguntabas, te regañaba en vez de explicar. Califica muy rudo, tanto tareas como exámenes y proyecto.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '5d6746d6c909247aab4f64d2f15c4201fa3527a14a85e6b16937546afc1e4dbd'::TEXT, ARRAY[2464]::BIGINT[]),
    (54::BIGINT, 'No explica la materia correctamente, grita mucho en clases, muy sarcástico. Lo único bueno es que promueve la participación del estudiante.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'd502bb584c4e289eaa327e80df2aaf29371fb3b66d25ebb8b429b0c84d59ca0c'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Ha mejorado mucho desde la primera vez que tuve su clase. Ahora le gusta que usted tenga opinión y fundamente lo que dice en clase. Algunas veces es un poco sarcástico y ayuda en tutorías.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'c01e18f8b08aa2b3f2ca2656bede5b9b26da7cc9aa2414d6b9e8801e60f704e9'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'Como persona es muy buena, pero lo importante es como es como profesor y es pésimo, no sabe transmitir sus conocimientos, a veces es sarcástico para decir que las cosas están malas y explica totalmente diferente a los libros utilizados en clases, no califica según el libro sino con sus conocimientos'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f743ac705fd20b6f7677ebccf289b2ee4c5654136a9195d74b37652b489b5337'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'En lo personal lo considero un mal profesor, tiene todo el conocimiento pero no sabe transmitirlo. Además, es sumamente pedante y no sabe como tratar a los estudiantes, falta el respeto a los estudiantes pero parece que no se da cuenta. No le presta importancia al proyecto y no ayuda. Califica duro'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9d6a0955fe14aa8d80a4eb1d8764772fbc0578212d79ab49dc5a20d740512514'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8e006897528569d6ce6cb62f42dcffb3c1a1e9c4b3875ce9a1fe4da676bde229'::TEXT, ARRAY[1892]::BIGINT[]),
    (54::BIGINT, 'No es buen profesor, no da instrucciones claras y aveces es pedante. La materia es fácil pero la complica y todo lo soluciona con "autogestión".'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'e7cb80814160f36781c1d8c5609b1b861a765e658369b72ea095f0798ebc7d9b'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Excelente profe, muy exigente, ayuda siempre que se le pide, examenes fáciles, explica muy bien y da ejemplos claros. Recomendadísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'fae60404179a04d3b0c46d3acdab3d93b4ded9fc523e6b9d8da7fa6aacf21235'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Muy buen profesor, sin embargo, trata a los estudiantes como personas inferiores y decepcionantes si no saben algo u opinan diferente a él, por lo cual no volvería a llevar un curso con este profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2016-10-29T00:00:00+00:00'::TIMESTAMPTZ, '8ca4915c1ae344b492324a9987632d61c26ee7046268352254a6ecfabd48d497'::TEXT, ARRAY[2454]::BIGINT[]),
    (54::BIGINT, 'El mejor profe del mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'ec133384ccb99070e97e0383e76bdb3c766261ccfdbf03b4125675a23e7ad992'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Excelente profesor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c2628a5c34243d327c8f13324932151c1c699d0eab61b0cad05ea22e889780f3'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Simplemente excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '647fba65ece03a3fe7196c02fcc5dab8d4f8b6cbab50157c8f42a576beb37eff'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Se aprende demasiado con este profe. De verdad quiere que los estudiantes sean profesionales excelentes. La materia la da con claridad(explica excelente), las clases son dinámicas, divertidas. Hay que realizar muchos trabajos, exigen lo mejor de los estudiantes. De verdad se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9ee7fd2279ddeecf05c3c86610e8455ac7f09335939bf87cf04fb40715e82ef9'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Super recomendado! Es muy buen profe, sabe mucho. Si deja mucho trabajillos pero se aprende, los exámenes son muy accesibles, se pasa con buena nota! Es una persona muy considerada con el estudiante, siempre tratando de ayudar sin embargo no regala la nota!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '852c4aa614ca7c17b3609ef3d7e4d8cdd29a6a5b6e63978c013730fb78c21fc1'::TEXT, ARRAY[2374]::BIGINT[]),
    (54::BIGINT, 'Excelente profesor, sabe lo que habla trasmite mucho conocimiento y se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f1752903cf3196c5ecf5fa5be14dccf692533011b6fdc6a9ea8767cc9868b0f5'::TEXT, ARRAY[2374]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
